using IptvManagement.Application.Abstractions; using IptvManagement.Infrastructure.Data; using IptvManagement.Infrastructure.Identity; using IptvManagement.Infrastructure.Security; using IptvManagement.Infrastructure.Services; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection;
namespace IptvManagement.Infrastructure;
public static class DependencyInjection{ public static IServiceCollection AddInfrastructure(this IServiceCollection services,IConfiguration cfg){ services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(cfg.GetConnectionString("DefaultConnection"))); services.AddDataProtection(); services.AddIdentity<ApplicationUser,IdentityRole>(o=>{ o.Password.RequiredLength=12; o.Password.RequireDigit=true; o.Password.RequireUppercase=true; o.Lockout.MaxFailedAccessAttempts=5; o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15); }).AddEntityFrameworkStores<AppDbContext>().AddDefaultTokenProviders(); services.AddScoped<ITokenService,TokenService>(); services.AddScoped<IStreamUrlProtector,StreamUrlProtector>(); services.AddScoped<IPlaylistService,PlaylistService>(); services.AddScoped<ISubscriptionService,SubscriptionService>(); services.AddScoped<IInvoiceService,InvoiceService>(); services.AddScoped<IDashboardService,DashboardService>(); services.AddScoped<IAdminDataService,AdminDataService>(); services.AddHostedService<ExpiredSubscriptionWorker>(); services.AddHostedService<ActivationCodeCleanupWorker>(); return services; }}
